import{_ as t,o as r,c as a,ag as o}from"./chunks/framework.2cFhd8Ux.js";const p=JSON.parse('{"title":"Upper-Division, Graduate, and Semester-Length AI-Assisted SE Courses: Research for the Course A / Course B Split","description":"","frontmatter":{"source":"research/notes/courses-upper-division.md"},"headers":[],"relativePath":"research/notes/courses-upper-division.md","filePath":"research/notes/courses-upper-division.md"}'),s={name:"research/notes/courses-upper-division.md"};function n(i,e,l,u,d,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="upper-division-graduate-and-semester-length-ai-assisted-se-courses-research-for-the-course-a--course-b-split" tabindex="-1">Upper-Division, Graduate, and Semester-Length AI-Assisted SE Courses: Research for the Course A / Course B Split <a class="header-anchor" href="#upper-division-graduate-and-semester-length-ai-assisted-se-courses-research-for-the-course-a--course-b-split" aria-label="Permalink to &quot;Upper-Division, Graduate, and Semester-Length AI-Assisted SE Courses: Research for the Course A / Course B Split&quot;">​</a></h1><p>Research notes compiled 2026-11-02 for the split of &quot;Building Software with AI&quot; (since renamed <em>Building Apps with AI</em>) into Course A (CS 2xxx, campus-wide, one prior programming course) and Course B (&quot;Engineering Software with AI&quot;, CS 4xxx/5xxx joint-listed, prereq CS 3383).</p><p><strong>Scope and method.</strong></p><ul><li>These notes are a delta on <code>research/notes/university-courses.md</code> (2026-09-25), <code>research/notes/2026-10/university-courses-fall-2026.md</code> (2026-10-21), and <code>research/landscape-report-2026-09.md</code>. Courses already covered there are revisited only where new week-by-week or assignment detail is now public.</li><li>Primary sources were read directly where possible: course sites fetched with curl, GitHub repos read through the GitHub API, PDFs converted with pdftotext.</li><li>Claims that rest only on a search-engine summary are marked &quot;(search summary)&quot;. Anything I infer is marked <strong>Inference</strong>.</li><li>One CMU 15-113 source is a draft paper linked from the public course site but marked &quot;In submission. Do not distribute.&quot; I paraphrase it briefly and do not quote it at length.</li></ul><hr><h2 id="q1-semester-length-upper-division-and-graduate-courses-on-ai-assisted--agentic-se-fall-2025--fall-2026-spring-2027" tabindex="-1">Q1. Semester-length upper-division and graduate courses on AI-assisted / agentic SE (Fall 2025 – Fall 2026; Spring 2027) <a class="header-anchor" href="#q1-semester-length-upper-division-and-graduate-courses-on-ai-assisted--agentic-se-fall-2025--fall-2026-spring-2027" aria-label="Permalink to &quot;Q1. Semester-length upper-division and graduate courses on AI-assisted / agentic SE (Fall 2025 – Fall 2026; Spring 2027)&quot;">​</a></h2><h3 id="summary-table-new-or-newly-detailed-courses" tabindex="-1">Summary table (new or newly detailed courses) <a class="header-anchor" href="#summary-table-new-or-newly-detailed-courses" aria-label="Permalink to &quot;Summary table (new or newly detailed courses)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Course</th><th>Level / prereq</th><th>Length</th><th>Weights</th><th>Tools / cost</th><th>Project model</th></tr></thead><tbody><tr><td>UT Austin CS 378 Agentic Software Engineering (Fall 2026)</td><td>Upper-div; C S 439 (systems)</td><td>15 wks, Tue/Thu</td><td>Quizzes 12, HW 58, final project 30</td><td>Codex + Claude Code via university accounts, $0</td><td>4 HWs (solo or pairs, new partner each time), peer PR round, solo/pair final with live defense</td></tr><tr><td>Michigan EECS 498-016 AASE (Fall 2026, update)</td><td>ULCS; EECS 281+201</td><td>15 wks, 4 cr</td><td>Admin 10, Apply 18, Analyze 22.5, Create 49.5</td><td>Ollama/Aider, then Codex via U-M GPT Toolkit, $0</td><td>All individual; projects moved into Aider&#39;s real codebase</td></tr><tr><td>UMD CMSC 389A Modern SW Dev with GenAI (Fall 2026)</td><td>Sophomore+; CMSC216+250</td><td>16 wks, 3 cr</td><td>Projects 40, final project 15, quizzes 5, 2 midterms 20, final 10, participation 10</td><td>Claude Pro required, $20/mo</td><td>Pair/group projects plus final project</td></tr><tr><td>UVA CS 4501 Modern SE with LLMs (Fall 2026)</td><td>4xxx; DS2 required</td><td>15 wks</td><td>Attendance 20, quizzes 20, assignments 20, project 40</td><td>Not stated</td><td>Small-team project, weeks 9–15</td></tr><tr><td>ANU COMP4020/8020 Agentic Coding Studio (Sem 2 2026)</td><td>UG + PG</td><td>12 wks</td><td>Crits 20, A1 20, A2 20, final 40</td><td>Claude Code, GitHub Pages, Fly.io</td><td>Weekly studio crits; full-stack multi-user final</td></tr><tr><td>Cornell CS 6158 SE in the Era of AI (Fall 2026)</td><td>PhD/MS seminar</td><td>16 wks</td><td>Participation 20, presentations 20, assignments 10, project 50</td><td>Not stated</td><td>Research project in pairs</td></tr><tr><td>CU Boulder CSCI 7000-05 Building AI Agents (Spring 2026)</td><td>Grad seminar</td><td>15 wks</td><td>Participation 10, critiques 20, presentation 20, project 50</td><td>Not stated</td><td>Teams of 3–4, research or &quot;novel-industrial&quot;</td></tr><tr><td>NC State GAI4SE (Fall 2025)</td><td>Research-oriented; level not stated on README</td><td>~15 wks</td><td>(syllabus is a Google Doc; not read)</td><td>—</td><td>Group project + Kaggle competition + midterm</td></tr></tbody></table><h3 id="ut-austin-cs-378-agentic-software-engineering-fall-2026-emmett-witchel" tabindex="-1">UT Austin CS 378 &quot;Agentic Software Engineering&quot; (Fall 2026, Emmett Witchel) <a class="header-anchor" href="#ut-austin-cs-378-agentic-software-engineering-fall-2026-emmett-witchel" aria-label="Permalink to &quot;UT Austin CS 378 &quot;Agentic Software Engineering&quot; (Fall 2026, Emmett Witchel)&quot;">​</a></h3><p>The most fully published new course, and the closest to Course B in level, though it leans toward systems rather than SE.</p><p><strong>Framing and grading</strong></p><ul><li>It treats &quot;use of AI coding agents as a form of technical writing that should be practiced and can be improved&quot;: students learn to split a problem into &quot;what you specify, what you delegate, and what you verify.&quot; Prereq: C S 439 plus Python and git; &quot;No prior AI/ML experience required.&quot; Topic mix: agent tools and architecture 30%, systems 25%, SE 20%, how models work 10%, tooling 15%. — <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378 home</a></li><li>Weights: end-of-class quizzes 12%, homeworks 58%, final project 30%. Each class ends with a 5-minute, 3-question quiz (four lowest dropped), and each homework due date opens with a 7-minute individual quiz on that homework. All quizzes are AI-free, with &quot;only a single browser tab open.&quot; — <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378 home</a></li></ul><p><strong>Homework design</strong></p><ul><li>Homeworks arrive &quot;in beats&quot;: &quot;you build v1 against a spec, then the spec changes under you — new drops arrive mid-homework, the way real software changes.&quot; — <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378 home</a></li><li>HW0 dotfiles (completion); HW1 email-index (search engine, then &quot;resilience: mutation, crashes &amp; concurrent search&quot;); HW2 tm-compute (rank Turing machines &quot;under a tight compute budget&quot;, then a &quot;PR round in a peer&#39;s repo&quot;); HW3 concurrent-index (race a baseline, compare two design variants, &quot;synthesize a design based on evidence&quot;); HW4 pdf2md (auditable tables from PDFs, then arXiv transfer). Pairs are allowed but &quot;you must work with a different partner each time.&quot; Each writeup includes self-contained insight slides, some shown in class. — <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378 home</a></li></ul><p><strong>Final project, tools, and process evidence</strong></p><ul><li>Solo or pair; 2-point proposal, 23-point repository plus live defense, 5-point slide writeup (six slides, &quot;including two design or evaluation decisions and a debugging story&quot;). &quot;Feature count, repository size, token spend, prompt volume, and visual polish do not substitute for demonstrated behavior, reproducible checks, controlled engineering decisions, or honest limitations.&quot; — <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378 home</a></li><li>Codex and Claude Code are provided through ChatGPT Edu and UT&#39;s Claude access, with &quot;no personal subscription cost&quot;. Students manage their own credits (&quot;It is not acceptable to turn in a homework with a note that, &#39;I would have done X, but I ran out of credit…&#39;&quot;), and the course concedes that &quot;students who add more generous personal subscriptions have an advantage.&quot; &quot;Commit history is part of the evaluation&quot;, and forum hints stay &quot;deliberately vague&quot; because &quot;AI agents often need only a hint.&quot; — <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378 home</a></li></ul><p><strong>Week-by-week (condensed)</strong> — <a href="https://www.cs.utexas.edu/~witchel/378AC/schedule.html" target="_blank" rel="noreferrer">CS 378 schedule</a></p><ul><li>W1 setup, coding-agent fundamentals · W2 token efficiency, workflow skills, &quot;Models should verify each other&quot;; SQLite · W3 <strong>prompt injection and the lethal trifecta; permissions and sandboxing</strong>; crash consistency; maintaining agent guidance · W4 WAL; <strong>&quot;Parallelize a task once you can name its merge point&quot;</strong> · W5 how assumptions become architecture; git data model; pull requests · W6 quiz, guests · W7–8 concurrency, linearizability, performance; PR round; mid-semester feedback; proposal due · W9 protecting secrets; <strong>using secrets safely with agents</strong> · W10 virtualization, containers, GPUs, serving · W11–12 what a language model is, transformers, pre/post-training · W13 <strong>&quot;Rewards and benchmarks: A test suite rewards and grades until its answers leak&quot;</strong> · W15 demos and defense.</li><li>Extra decks include &quot;Sandbox mechanics: namespaces, cgroups &amp; seccomp&quot; and &quot;Claude Code Unpacked: the agent loop, mapped from source&quot;.</li></ul><h3 id="michigan-eecs-498-016-aase-what-changed-since-the-baseline" tabindex="-1">Michigan EECS 498-016 AASE: what changed since the baseline <a class="header-anchor" href="#michigan-eecs-498-016-aase-what-changed-since-the-baseline" aria-label="Permalink to &quot;Michigan EECS 498-016 AASE: what changed since the baseline&quot;">​</a></h3><p><strong>Schedule now published through Week 10.</strong> L01–L04 cover the landscape, how LLMs code, context/model/prompt, and spec-driven development; L05–L11 agentic CLIs, orchestration, the raw call, Hackathon 1, stop conditions and approval, skills and the Elephant-Goldfish Model, guardrails; L12 is a course feedback session; L13–L18 browser extensions, subagents, compaction and caching, memory, knowledge bases, &quot;Many Models, One Harness&quot;. Weeks 11–15 are TBD. — <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">AASE syllabus</a></p><p><strong>The Analyze phase was rebuilt</strong></p><ul><li>P2 is now &quot;Aider as an agent&quot;. It has four parts (a skills loader, a model-driven tool loop, a shell tool behind approval rules, and a stdio MCP client), graded 50% design and 50% working behavior. An &quot;Elephant design document and Goldfish review ledger&quot; must be committed before implementation. — <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">AASE syllabus</a></li><li>The former agent-v0 eval suite and teardown report &quot;are no longer required.&quot; — <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">AASE syllabus</a></li><li>From Lab 03 everyone uses Codex with a Luna model &quot;on course-provided credit&quot;. The expected cost stays &quot;$0&quot;. — <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">AASE syllabus</a></li></ul><p><strong>Why it changed (Lab03 slides)</strong></p><ul><li>The lab &quot;replaces the &#39;Build the agent&#39; lab.&quot; — <a href="https://github.com/eecs498-aase/materials/blob/HEAD/labs/Lab03/slides.md" target="_blank" rel="noreferrer">Lab03 slides</a></li><li>49 students answered &quot;If you had Codex for the rest of the course, what would you want to learn?&quot; About 23 wanted to learn to use the tools well, 8 design and specs, 7 orchestration and skills, and 5 context and tokens. &quot;Almost nobody asked what to build with it.&quot; — <a href="https://github.com/eecs498-aase/materials/blob/HEAD/labs/Lab03/slides.md" target="_blank" rel="noreferrer">Lab03 slides</a></li><li>The new work is in &quot;the real Aider… About 20,000 lines of Python with 12,000 lines of tests&quot;. The required order is &quot;Learn, then design, then build&quot;, because &quot;A one-shot prompt gives you the model&#39;s design, not yours.&quot; — <a href="https://github.com/eecs498-aase/materials/blob/HEAD/labs/Lab03/slides.md" target="_blank" rel="noreferrer">Lab03 slides</a></li></ul><h3 id="umd-cmsc-389a-modern-software-development-with-genai-fall-2026-anwar-mamat" tabindex="-1">UMD CMSC 389A &quot;Modern Software Development with GenAI&quot; (Fall 2026, Anwar Mamat) <a class="header-anchor" href="#umd-cmsc-389a-modern-software-development-with-genai-fall-2026-anwar-mamat" aria-label="Permalink to &quot;UMD CMSC 389A &quot;Modern Software Development with GenAI&quot; (Fall 2026, Anwar Mamat)&quot;">​</a></h3><p>This is a new 3-credit course. It is separate from the 1-credit CMSC 398Z in the baseline.</p><p><strong>Logistics and cost</strong></p><ul><li>Prereq: CMSC216 and CMSC250. Students &quot;are required to purchase their own Claude Code subscription at the Pro level ($20/month).&quot; — <a href="https://www.cs.umd.edu/class/fall2026/cmsc389A/Syllabus.html" target="_blank" rel="noreferrer">389A syllabus</a></li><li>Weights: projects 40, final project 15, quizzes 5, midterm 1 10, midterm 2 10, final exam 10, in-class participation and exercises 10. — <a href="https://www.cs.umd.edu/class/fall2026/cmsc389A/Syllabus.html" target="_blank" rel="noreferrer">389A syllabus</a></li></ul><p><strong>Outcomes and topics</strong></p><ul><li>Outcomes include TDD, &quot;property-based and coverage-based tests&quot;, &quot;evaluate AI-generated test suites&quot;, &quot;manual vs. AI review&quot;, and &quot;concurrent agents, git worktrees&quot;. — <a href="https://www.cs.umd.edu/class/fall2026/cmsc389A/Syllabus.html" target="_blank" rel="noreferrer">389A syllabus</a></li></ul><p><strong>Schedule so far:</strong> W1 &quot;This Is Not an AI Class&quot;, Claude Code files, Git/CI (A1 side-scroller game); W2–3 FastAPI, MySQL, React/TypeScript (A2 clicker quiz game); W4 auth/CORS, Docker, Redis; W5–6 how LLMs work, Midterm 1; W7 <strong>&quot;The Elephant-Goldfish Model&quot;</strong> borrowed from Michigan (A3 quiz generator); W8–9 RAG, prompt evaluation, Ollama, LLM APIs; W10–16 not yet posted. — <a href="https://www.cs.umd.edu/class/fall2026/cmsc389A/Schedule.html" target="_blank" rel="noreferrer">389A schedule</a></p><h3 id="stanford-cs146s-week-5-posted-2026-10-26-agent-readiness-report" tabindex="-1">Stanford CS146S Week 5 (posted 2026-10-26): &quot;Agent-Readiness Report&quot; <a class="header-anchor" href="#stanford-cs146s-week-5-posted-2026-10-26-agent-readiness-report" aria-label="Permalink to &quot;Stanford CS146S Week 5 (posted 2026-10-26): &quot;Agent-Readiness Report&quot;&quot;">​</a></h3><ul><li>Students run Factory&#39;s <code>/readiness-report</code> on <strong>three</strong> OSS repos that &quot;differ in language, size, and age&quot;. It scores &quot;60+ criteria across the eight pillars&quot;.</li><li>They then answer: which pillars failed most and why; &quot;the cheapest high-leverage fix&quot; per repo; and &quot;where the framework falls short&quot;. &quot;Three repos is a small sample. Scope your claims to what it supports.&quot;</li><li>Rubric: reports 40, analysis 60.</li><li>— <a href="https://github.com/mihail911/modern-software-dev-assignments/blob/df18839a81/week5/assignment.md" target="_blank" rel="noreferrer">W5 spec @ df18839a81</a></li><li>As of 2026-11-02 the repo contains week1–week5 only. The site still lists &quot;Open Source Contributions 30%&quot; but publishes no rubric. — <a href="https://github.com/mihail911/modern-software-dev-assignments/commits/master" target="_blank" rel="noreferrer">repo commits</a>; <a href="https://themodernsoftware.dev/" target="_blank" rel="noreferrer">CS146S site</a></li></ul><h3 id="other-semester-courses" tabindex="-1">Other semester courses <a class="header-anchor" href="#other-semester-courses" aria-label="Permalink to &quot;Other semester courses&quot;">​</a></h3><p><strong>UVA CS 4501 &quot;Modern Software Engineering with LLMs&quot; (Fall 2026).</strong> Weeks 1–8 cover LLM basics, workflows and agents, what and how to build, quality control, and tech and global dilemmas; weeks 9–15 are the team project (launch, MVP, update, alpha, <strong>red teaming</strong> in week 13, future, fair). Weights: attendance 20, quizzes 20, assignments 20, project 40. — <a href="https://www.cs.virginia.edu/~se4ja/files/seLLMs2026.html" target="_blank" rel="noreferrer">UVA 2026</a></p><p><strong>ANU COMP4020/8020 &quot;Agentic Coding Studio&quot; (Semester 2, 2026)</strong></p><ul><li>Format: weekly lecture plus a studio &quot;crit&quot; with groups of about 20 led by a tutor. — <a href="https://comp.anu.edu.au/courses/comp4020-agentic-coding-studio/" target="_blank" rel="noreferrer">ANU course site</a></li><li>A &quot;static half&quot; in which everything &quot;deploys to GitHub Pages&quot; is followed by a full-stack half on Fly.io. — <a href="https://comp.anu.edu.au/courses/comp4020-agentic-coding-studio/" target="_blank" rel="noreferrer">ANU course site</a></li><li>Lecture titles: Introduction · Specs and self-portrait · Backpressure · Context engineering · Verification · Evidence of practice · Full stack · Decision records and persistence · Subagents and real-time · Logs, harnesses and multi-user apps · AMA. — <a href="https://comp.anu.edu.au/courses/comp4020-agentic-coding-studio/lectures/" target="_blank" rel="noreferrer">ANU lectures</a></li><li>A1 and A2 &quot;are marked on the legibility of your process&quot;. The final project includes &quot;a definition of good that you make and defend&quot;. — <a href="https://comp.anu.edu.au/courses/comp4020-agentic-coding-studio/" target="_blank" rel="noreferrer">ANU course site</a></li></ul><p><strong>Cornell CS 6158 &quot;Software Engineering in the Era of AI&quot; (Fall 2026, Saikat Dutta).</strong> Weeks 1–5 cover SE basics (program analysis, testing, security) and LLM basics; weeks 6–14 are paper sessions on evaluation (SWE-smith, SWE-EVO, ProgramBench), security of agents, agent adaptation (SWE-Gym, SpecBench reward hacking), flaky tests, verification, code translation, fuzzing with agents, and specification inference; weeks 15–16 are project presentations. — <a href="https://www.cs.cornell.edu/courses/cs6158/2026fa/schedule.html" target="_blank" rel="noreferrer">CS 6158 schedule</a></p><p><strong>CU Boulder CSCI 7000-05 &quot;Building AI Agents&quot; (Spring 2026, Danny Dig)</strong></p><ul><li>Mostly remote seminar. Readings include ReAct, Reflexion, Toolformer, SWE-agent, AutoCodeRover, MetaGPT, OpenHands, and &quot;Decoding the Configuration of AI Coding Agents: Insights from Claude Code Projects&quot;. — <a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/index.html" target="_blank" rel="noreferrer">CSCI 7000-05</a></li><li>Students run a &quot;Project Bazaar&quot; to form teams. — <a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/index.html" target="_blank" rel="noreferrer">CSCI 7000-05</a></li></ul><p><strong>NC State GAI4SE (Fall 2025, Bowen Xu)</strong> mixes lectures with guest research talks, a flipped &quot;AI Concept Video&quot;, a code-embedding take-home, a midterm, a Kaggle &quot;Code Backdoor Detection&quot; competition, and a group project with proposal and solution presentations. — <a href="https://github.com/gai4se/GAI4SE-Course" target="_blank" rel="noreferrer">GAI4SE README</a></p><p><strong>Paderborn &quot;Agentic Software Engineering&quot; (master&#39;s, WS 2026/27)</strong> covers RAG, tool use, context engineering, memory, economics, agent types, multi-agent/A2A, testing and symbolic feedback, reliability, security, and &quot;Human-in-the-loop, accountability, and code ownership&quot;, with six exercise sheets graded in pairs. — <a href="https://www.hni.uni-paderborn.de/en/sse/lehre/ase" target="_blank" rel="noreferrer">Paderborn ASE</a></p><p><strong>Spring 2027.</strong> No Spring 2027 course syllabus was found. Degree programs with 2027 entry exist (Monash&#39;s Bachelor of Agentic Software Engineering; Leicester&#39;s MSc Software Engineering with Agentic AI), and UMass Lowell announced &quot;AI Agents with Claude Code&quot; for Fall 2026 (all search summaries). — <a href="https://www.monash.edu/__data/assets/pdf_file/0007/4439896/2027-C2012-BASE.pdf" target="_blank" rel="noreferrer">Monash C2012 2027 PDF</a>; <a href="https://le.ac.uk/courses/software-engineering-with-agentic-ai-msc/2027" target="_blank" rel="noreferrer">Leicester MSc</a>; <a href="https://www.uml.edu/myuml/submissions/2026/2026-04-15-16-21-07-announcing-a-new-topics-course-ai.aspx" target="_blank" rel="noreferrer">UMass Lowell</a></p><h3 id="takeaway-for-course-b" tabindex="-1">Takeaway for Course B <a class="header-anchor" href="#takeaway-for-course-b" aria-label="Permalink to &quot;Takeaway for Course B&quot;">​</a></h3><p>The two strongest templates are <strong>UT Austin CS 378</strong> (individual craft, systems depth, evidence-graded final defense) and <strong>Michigan AASE after its pivot</strong> (work inside a real 20K-line agent codebase).</p><p>Practices worth copying from them:</p><ul><li>Homework &quot;beats&quot; where the spec changes mid-assignment.</li><li>A short no-AI quiz at the start of each homework due date.</li><li>A peer PR round in classmates&#39; repos.</li><li>Rotating partners.</li><li>A final defense graded on &quot;demonstrated behavior, reproducible checks… honest limitations&quot; rather than feature count.</li><li>University-provided agents. Course B&#39;s $0 rule needs an equivalent: Michigan&#39;s course credit, UT&#39;s university accounts, or local models.</li></ul><p><strong>Inference:</strong> Michigan dropped two plans. One was building an agent from scratch on a small model; the other was a stand-alone eval-suite project. Course B&#39;s &quot;build a ~200-line agent&quot; therefore works best as a short early lab, not a multi-week project. It should then be followed by extending a real open-source harness, which also serves the &quot;large existing codebase&quot; goal.</p><hr><h2 id="q2-team-projects-on-existing-open-source-codebases" tabindex="-1">Q2. Team projects on existing open-source codebases <a class="header-anchor" href="#q2-team-projects-on-existing-open-source-codebases" aria-label="Permalink to &quot;Q2. Team projects on existing open-source codebases&quot;">​</a></h2><h3 id="how-courses-run-them" tabindex="-1">How courses run them <a class="header-anchor" href="#how-courses-run-them" aria-label="Permalink to &quot;How courses run them&quot;">​</a></h3><p><strong>CMU 17-313 Foundations of SE (Fall 2026): a class fork of a real agent codebase</strong></p><ul><li>&quot;This semester, we will be building upon opencode, the open source AI coding agent.&quot; Students fork &quot;a class-specific fork of opencode&quot; (<code>CMU-313/opencode</code>). &quot;We will ONLY be working with the course specific repo in this class.&quot; — <a href="https://cmu-313.github.io/assignments/P1/" target="_blank" rel="noreferrer">17-313 P1</a></li><li>P1B onboarding (95 pts) asks students to remove one or more Qlty-reported code smells by refactoring and to validate the change, plus TypeScript self-study. — <a href="https://cmu-313.github.io/assignments/P1/2_refactoring/" target="_blank" rel="noreferrer">P1B</a></li><li>In P2 sprints, each student owns one backlog issue on a named branch with a PR to the team repo that has &quot;at least some teammate review&quot;. &quot;The PR does not need to be merged yet.&quot; Grading uses &quot;a snapshot of your repository (including open branches and PRs)&quot; at the deadline. &quot;You should not submit your changes to the parent opencode repository.&quot; — <a href="https://cmu-313.github.io/assignments/P2/2_firstsprint/" target="_blank" rel="noreferrer">P2B</a></li><li>Checkpoint slides must include a video demo or, &quot;if you were not able to make a working build&quot;, screenshots that explain &quot;what factors impeded your progress.&quot; — <a href="https://cmu-313.github.io/assignments/P2/2_firstsprint/" target="_blank" rel="noreferrer">P2B</a></li></ul><p><strong>Michigan AASE (Fall 2026)</strong> moved its projects into Aider&#39;s real codebase (above). Whether students send PRs upstream is not stated. — <a href="https://github.com/eecs498-aase/materials/blob/HEAD/labs/Lab03/slides.md" target="_blank" rel="noreferrer">Lab03 slides</a></p><p><strong>Stanford CS146S (Fall 2026)</strong> grades &quot;Open Source Contributions&quot; at 30% and names 15 &quot;Open Source Partners&quot; (OpenHands, marimo, CrewAI, Semgrep, Milvus, Unsloth, cmux, pi.dev, Arize Phoenix, Browserbase, CopilotKit, HeyGen, Vercel, Warp, Anyscale), but no contribution rubric is public. Weeks 3–5 all work on unfamiliar OSS repos: a skill, an AGENTS.md for &quot;a repo you did not write&quot;, and a three-repo readiness comparison. — <a href="https://themodernsoftware.dev/" target="_blank" rel="noreferrer">CS146S site</a>; <a href="https://github.com/mihail911/modern-software-dev-assignments/blob/a6dcbf2090/week4/assignment.md" target="_blank" rel="noreferrer">W4 spec</a>; <a href="https://github.com/mihail911/modern-software-dev-assignments/blob/df18839a81/week5/assignment.md" target="_blank" rel="noreferrer">W5 spec</a>. <strong>Inference:</strong> the partner list plus three onboarding assignments look like a deliberate on-ramp to upstream PRs with maintainers who agreed in advance.</p><p><strong>UT Austin CS 378 PR round (peer repos instead of upstream)</strong></p><ul><li>&quot;every student or pair opens one real pull request against a classmate&#39;s tm-compute repository and reviews the pull request that lands on their own&quot;, on &quot;a fixed one-week clock&quot;. — <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378 home</a></li><li>Repos that fail staff checks are left out of the ring and scored 50/100. A declared opt-out also gets 50. Not showing up scores 0. — <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378 home</a></li></ul><p><strong>Pre-AI upstream-contribution courses (data on merge rates and grading)</strong></p><ul><li><strong>Michigan EECS 481</strong>, 2018–2022 (Fang, Endres, Weimer et al., FSE 2023): <ul><li>Scale: 1,361 students; 984 reports; 443 projects.</li><li>Process: students picked a GitHub project, found an open issue, built it locally, and submitted a PR, with a project plan and a final reflection. &quot;Extra credit points were awarded for contributions merged… before the end of the semester.&quot;</li><li>Acceptance: <strong>44% of student PRs were accepted</strong>. Solo 47% (266/561) vs pairs 39% (166/428). OSS-for-social-good projects 53% vs 40%.</li><li>Experience: 42% found it more stressful than expected; 1.6% called it terrible.</li><li>The authors&#39; advice: &quot;avoid mandatory grading of whether pull requests are accepted.&quot;</li><li>— <a href="https://web.eecs.umich.edu/~weimerw/p/weimer-fse2023.pdf" target="_blank" rel="noreferrer">Fang et al. FSE 2023 PDF</a></li></ul></li><li><strong>Other merge-rate data.</strong> Seneca OSD600, Fall 2021: 54 students, 392 PRs, 277 merged (70%, up from 63% in 2019), with 7–10 upstream PRs of growing complexity alongside labs where students maintain each other&#39;s tool; lesson: students &quot;should make smaller PRs&quot;. — <a href="https://blog.humphd.org/teaching-open-source-fall-2021/" target="_blank" rel="noreferrer">humphd blog</a>. Toronto ECE444&#39;s &quot;Open Source Excursion&quot; listed 46 merged PRs across 40 projects in Fall 2024 (my count), running since 2020. — <a href="https://www.eecg.toronto.edu/~shuruiz/course/UofT-ECE444/showcase.html" target="_blank" rel="noreferrer">ECE444 showcase</a>. UIUC CS 491TC (Fall 2018) graded 25% on FOSS work at &quot;+2½% per contributive effort&quot; and &quot;+12½% per accepted pull request.&quot; — <a href="https://relate.cs.illinois.edu/course/cs491tc-fa18/page/contrib/" target="_blank" rel="noreferrer">CS 491TC</a></li><li><strong>Cassee et al.</strong> (ICSE-SEET 2026) studied a master&#39;s SE course in Europe: <ul><li>New barriers: &quot;Conflicting Mentor Guidance&quot; and &quot;Communication Channel Ambiguity&quot;.</li><li>Per the abstract (paraphrased), commit frequency predicted contribution success better than project size or age, and students who chose projects by personal interest succeeded more often.</li><li>Recommendation (paraphrased): educators should use project-vitality metrics and prepare students for common barriers.</li><li>— <a href="https://research.tue.nl/en/publications/what-barriers-do-students-experience-when-trying-to-contribute-to/" target="_blank" rel="noreferrer">TU/e record</a>; <a href="https://conf.researchr.org/details/icse-2026/icse-2026-software-engineering-education-and-training--seet-/27/What-barriers-do-students-experience-when-trying-to-contribute-to-Open-Source-Softwar" target="_blank" rel="noreferrer">ICSE 2026 listing</a></li></ul></li></ul><h3 id="maintainer-ai-policies-and-the-2026-environment" tabindex="-1">Maintainer AI policies and the 2026 environment <a class="header-anchor" href="#maintainer-ai-policies-and-the-2026-environment" aria-label="Permalink to &quot;Maintainer AI policies and the 2026 environment&quot;">​</a></h3><p><strong>Policy landscape</strong></p><ul><li>Hora and Robbes analyzed 1,000 popular repos and found 118 contributor AI policies. Of these, 78% allow AI-assisted contributions, 22% discourage AI use, 51% require disclosure, and 74% require a human in the loop. — <a href="https://arxiv.org/abs/2605.16706" target="_blank" rel="noreferrer">arXiv 2605.16706</a></li></ul><p><strong>Three primary-source examples spanning the range</strong></p><ul><li><strong>QEMU (ban):</strong> &quot;Current QEMU project policy is to DECLINE any contributions which are believed to include or derive from AI generated content&quot;. The stated reason is DCO and copyright uncertainty. Using AI for &quot;researching APIs… static analysis, or debugging&quot; is allowed if the output is not included. — <a href="https://github.com/qemu/qemu/blob/master/docs/devel/code-provenance.rst" target="_blank" rel="noreferrer">QEMU code-provenance.rst</a></li><li><strong>Ghostty (strict disclosure):</strong><ul><li>&quot;All AI usage in any form must be disclosed&quot;. &quot;If you can&#39;t explain what your changes do… do not contribute&quot;.</li><li>&quot;Bad AI drivers will be denounced&quot; on a public list that &quot;will block all future contributions.&quot;</li><li>&quot;if you&#39;re interested in [learning]… don&#39;t use AI, and we&#39;ll help you.&quot;</li><li>— <a href="https://github.com/ghostty-org/ghostty/blob/main/AI_POLICY.md" target="_blank" rel="noreferrer">Ghostty AI_POLICY.md</a></li></ul></li><li><strong>LLVM (human in the loop):</strong><ul><li>&quot;Contributors must read and review all LLM-generated code&quot;; new contributors should &quot;start with small contributions&quot;; &quot;Passing maintainer feedback to an LLM doesn&#39;t help anyone grow&quot;.</li><li>Disclosure uses a trailer such as <code>Assisted-by:</code>. PR descriptions should be written by the contributor.</li><li>Agents acting &quot;without human approval, such as the GitHub <code>@claude</code> agent&quot; are banned.</li><li>— <a href="https://github.com/llvm/llvm-project/blob/main/llvm/docs/AIToolPolicy.md" target="_blank" rel="noreferrer">LLVM AIToolPolicy.md</a></li></ul></li></ul><p><strong>Platform and community responses to low-quality PRs</strong></p><ul><li>GitHub added settings in February 2026 to disable PRs or restrict them to collaborators, and in June 2026 an open-PR cap for non-collaborators that counts agent-opened PRs (cap details from a search summary). — <a href="https://github.com/orgs/community/discussions/187038" target="_blank" rel="noreferrer">GitHub discussion #187038</a>; <a href="https://visualstudiomagazine.com/articles/2026/06/30/github-extends-contribution-controls-from-prs-to-issues.aspx" target="_blank" rel="noreferrer">Visual Studio Magazine</a></li><li>Godot maintainers called AI PRs &quot;draining and demoralizing&quot; (search summary). — <a href="https://www.theregister.com/2026/02/18/godot_maintainers_struggle_with_draining/" target="_blank" rel="noreferrer">The Register, 2026-02-18</a></li><li><strong>Hacktoberfest 2026 dropped the PR challenge</strong> after &quot;a massive flood of activity and burnout from the rise of low-effort PRs&quot;, becoming one-day &quot;Fests&quot; about &quot;building with open source AI&quot;. — <a href="https://hacktoberfest.com/llms.txt" target="_blank" rel="noreferrer">hacktoberfest.com/llms.txt</a></li><li>In the AIDev dataset (456K agent PRs), acceptance was Codex 64%, Devin 49%, Copilot 35%, vs about 77% for humans (search summary of the paper). — <a href="https://arxiv.org/pdf/2507.15003" target="_blank" rel="noreferrer">arXiv 2507.15003</a></li><li>Cautionary case: in 2021 the Linux kernel banned contributions from the University of Minnesota after a research group submitted &quot;hypocrite commits&quot;; how IRB review was handled is disputed in the coverage. — <a href="https://www.theregister.com/2021/04/21/minnesota_linux_kernel_flaws_update/" target="_blank" rel="noreferrer">The Register, 2021-04-21</a>; <a href="https://lwn.net/Articles/854076/" target="_blank" rel="noreferrer">LWN</a>. <strong>Inference:</strong> one student&#39;s behavior can get a whole institution blocked, and Ghostty-style public denouncement lists make that easier in 2026.</li></ul><h3 id="takeaway-for-course-b-1" tabindex="-1">Takeaway for Course B <a class="header-anchor" href="#takeaway-for-course-b-1" aria-label="Permalink to &quot;Takeaway for Course B&quot;">​</a></h3><p>Run the semester project in <strong>three tiers</strong>.</p><ol><li><strong>Graded core work in a class fork</strong> of a real, active OSS codebase (the CMU 17-313 opencode model). <ul><li>Grade issues, branches, PRs, and team review from a deadline snapshot, so that nothing depends on maintainers.</li></ul></li><li><strong>A peer PR round</strong> across teams&#39; forks (the UT Austin model) to practice review at scale and CI gates.</li><li><strong>Optional upstream PRs</strong> to a short, pre-vetted list of projects. The list should meet five criteria: <ul><li>(a) a written AI policy that allows disclosed assistance (LLVM-style, not QEMU)</li><li>(b) high recent commit frequency and responsive maintainers (the Cassee et al. vitality metric)</li><li>(c) labeled good-first issues</li><li>(d) a maintainer contact made before the term</li><li>(e) no history of capping or closing outside PRs</li></ul></li></ol><p><strong>Grading.</strong> Follow Michigan&#39;s advice and grade <strong>process evidence</strong>, not merge status:</p><ul><li>issue discussion, a reproduction, tests, and a self-written PR description with an <code>Assisted-by</code> trailer</li><li>a responsive revision after review</li><li>a reflection</li></ul><p>Merges count as a bonus. Expect roughly 40–70% of PRs to merge based on pre-AI course data. <strong>Inference:</strong> expect lower rates in 2026, given maintainer pushback.</p><p><strong>Rules for students.</strong></p><ul><li>One open upstream PR per student per project.</li><li>No agent posting unattended in a maintainer&#39;s space.</li><li>Students must be able to explain every line before asking for review.</li><li>Staff screen PRs before submission for the first upstream round.</li></ul><hr><h2 id="q3-undergraduategraduate-differentiation-in-joint-listed-courses" tabindex="-1">Q3. Undergraduate/graduate differentiation in joint-listed courses <a class="header-anchor" href="#q3-undergraduategraduate-differentiation-in-joint-listed-courses" aria-label="Permalink to &quot;Q3. Undergraduate/graduate differentiation in joint-listed courses&quot;">​</a></h2><h3 id="uidahos-own-convention" tabindex="-1">UIdaho&#39;s own convention <a class="header-anchor" href="#uidahos-own-convention" aria-label="Permalink to &quot;UIdaho&#39;s own convention&quot;">​</a></h3><ul><li>UIdaho CS catalog entries for joint-listed courses state the graduate difference in one sentence.</li><li>The common wording is &quot;Additional projects/assignments required for graduate credit&quot;. Examples include CS 4200/5200, 4211/5211, 4380/5380, 4441/5441, 4502/5502, and 4602/5602. — <a href="https://catalog.uidaho.edu/courses/cs/" target="_blank" rel="noreferrer">UIdaho CS courses</a></li><li>Other wordings: <ul><li>&quot;Extra term paper required for graduate credit&quot; (CS 4701/5701 AI)</li><li>&quot;Additional class presentation and/or paper required for graduate credit&quot; (CS 4615/5615)</li><li>&quot;Graduate-level research and possible paper or presentation required for graduate credit&quot; (CS 4731/5731)</li><li>— <a href="https://catalog.uidaho.edu/courses/cs/" target="_blank" rel="noreferrer">UIdaho CS courses</a></li></ul></li><li>Registration rule B-11: a student &quot;may only earn credit at the level the student initially completes the course.&quot; — <a href="https://catalog.uidaho.edu/general-requirements-academic-procedures/b-registration/" target="_blank" rel="noreferrer">UIdaho catalog B-Registration</a></li><li><strong>Inference:</strong> the Course B catalog entry should name the graduate extra concretely, e.g., &quot;Additional paper presentations and an empirical study required for graduate credit.&quot; This matches local precedent and tells students what to expect.</li></ul><h3 id="what-other-dual-listed-courses-do" tabindex="-1">What other dual-listed courses do <a class="header-anchor" href="#what-other-dual-listed-courses-do" aria-label="Permalink to &quot;What other dual-listed courses do&quot;">​</a></h3><p><strong>Courses that publish a concrete graduate difference</strong></p><ul><li><strong>ANU COMP8020 vs COMP4020:</strong> &quot;As the 8000-level component, the portfolio also carries a short critical research note&quot; of about 1,000 words. It is worth 10% of the 40% final-project mark, so about 4% of the course. It is tied to the outcome &quot;Reflect on current approaches… and evaluate their limitations.&quot; — <a href="https://programsandcourses.anu.edu.au/2026/course/COMP8020/Second%20Semester/9057" target="_blank" rel="noreferrer">ANU COMP8020 P&amp;C</a></li><li><strong>CMU 17-445/645/745 (ML in Production):</strong> &quot;The course is the same under all course numbers, except for the PhD-level 17-745 number, which replaces two homework assignments with a mandatory research project.&quot; — <a href="https://mlip-cmu.github.io/f2025" target="_blank" rel="noreferrer">MLiP F2025</a></li></ul><p><strong>Courses that publish no graduate difference</strong></p><ul><li>CMU 17-316/616 — <a href="https://ai-developer-tools.github.io/syllabus/" target="_blank" rel="noreferrer">syllabus</a></li><li>UCSD CSE 190/291P (&quot;both 190 and 291P students attend the same lectures&quot;) — <a href="https://ucsd-cse-115-215.github.io/sp26/index.html" target="_blank" rel="noreferrer">UCSD SP26</a></li><li>UNC Charlotte ITCS 6010/8010 — <a href="https://marcovieira.me/teaching/itcs6010/" target="_blank" rel="noreferrer">ITCS 6010/8010</a></li><li>CWRU CSDS 393/493, which adds &quot;paper reviews&quot; for all students — <a href="https://sumonbis.github.io/courses/software-engineering" target="_blank" rel="noreferrer">CSDS 393/493</a></li><li>NJIT CS 485/698, which asks only that students without SE background do &quot;additional background reading&quot; (search summary) — <a href="https://kelloggm.github.io/martinjkellogg.com/teaching/cs485-sp26" target="_blank" rel="noreferrer">NJIT CS 485</a></li></ul><h3 id="published-rubrics-and-templates-for-graduate-extras" tabindex="-1">Published rubrics and templates for graduate extras <a class="header-anchor" href="#published-rubrics-and-templates-for-graduate-extras" aria-label="Permalink to &quot;Published rubrics and templates for graduate extras&quot;">​</a></h3><p><strong>CU Boulder CSCI 7000-05 (Danny Dig)</strong></p><ul><li><p><strong>Paper critique</strong> (one page, due before class) has six headings:</p><ol><li>What I liked</li><li>What I disliked</li><li>Future directions</li><li>Open questions</li><li>Most important for class discussion</li><li>Summary</li></ol><p>— <a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/paperCritiques.html" target="_blank" rel="noreferrer">Paper Critiques</a></p></li><li><p><strong>&quot;Tool Experience Report&quot; alternative:</strong> read the paper, download the tool, and &quot;use it for your own usecase&quot;. The report covers experience, strengths, weaknesses, potential for practical impact, and reflection, including &quot;one improvement&quot; for the tool&#39;s creators. — <a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/paperCritiques.html" target="_blank" rel="noreferrer">Paper Critiques</a></p></li><li><p><strong>Presentation rubric</strong> (two per student):</p><ul><li>30 points: presentation of the content</li><li>30 points: &quot;Value added to the content&quot; (hands-on activity, own analysis of the tool)</li><li>20 points: effectiveness of the materials</li><li>20 points: moderating discussion using classmates&#39; critique questions</li></ul><p>— <a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/paperPresentation.html" target="_blank" rel="noreferrer">Paper Presentation</a></p></li><li><p><strong>Project:</strong> &quot;research-oriented or… novel-industrial&quot;, teams of 3–4, a proposal, four milestones, and a final. — <a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/researchProject.html" target="_blank" rel="noreferrer">Research Project</a></p></li><li><p><strong>Weights:</strong> participation 10, critiques 20, presentation 20, project 50. — <a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/syllabus.html" target="_blank" rel="noreferrer">Syllabus</a></p></li></ul><p><strong>Cornell CS 6158 (Saikat Dutta).</strong> Each class has Presenter 1, Presenter 2, and a Discussant. Presenters give a 15–20 minute talk and lead 10–15 minutes of discussion from &quot;at least 5 questions&quot; drawn from classmates&#39; Perusall comments; discussants submit written answers to all Perusall questions; everyone else posts at least 2 questions per paper and rates presenters. Project milestones: 2-page proposal (W4), 5-minute pitch (W6), 2–3 page midterm report (W9), 5-page final report and 15-minute talk. Reviews may use AI &quot;to understand concepts&quot; but not to generate &quot;entire reviews&quot;. — <a href="https://www.cs.cornell.edu/courses/cs6158/2026fa/" target="_blank" rel="noreferrer">CS 6158 home</a></p><p><strong>NC State GAI4SE</strong> gives a &quot;What is a good presentation?&quot; checklist:</p><ul><li>&quot;Highlight the biggest take-aways&quot;</li><li>explain why the paper is important</li><li>explain the characteristics of the data</li><li>attend to technical details and present results properly</li><li>&quot;(Bonus) What can be done in the future?&quot;</li></ul><p>— <a href="https://github.com/gai4se/GAI4SE-Course" target="_blank" rel="noreferrer">GAI4SE README</a></p><h3 id="takeaway-for-course-b-2" tabindex="-1">Takeaway for Course B <a class="header-anchor" href="#takeaway-for-course-b-2" aria-label="Permalink to &quot;Takeaway for Course B&quot;">​</a></h3><p>UIdaho precedent and peer courses support graduate extras worth about <strong>15–25%</strong> of the 5xxx grade.</p><p><strong>Option A: graduate extras replace undergraduate work</strong> (the CMU 17-745 model)</p><ol><li>Two paper presentations, using the CU Boulder rubric, drawn from a reading list built from Cornell&#39;s and CU Boulder&#39;s schedules: SWE-agent, Agentless, SpecBench reward hacking, IFC for agents, AIDev agentic PRs, and METR/RCT productivity studies.</li><li>Weekly one-page critiques, with the Tool Experience Report as an alternative.</li><li>A <strong>small empirical study</strong> that replaces one or two undergraduate labs.</li></ol><p><strong>Option B: graduate extras added on top</strong> (the ANU model)</p><ul><li>A 1,000-word critical research note attached to the semester project.</li></ul><p><strong>Empirical studies should use the team&#39;s own data</strong>, such as:</p><ul><li>the team&#39;s own PR and review data</li><li>a mutation-score comparison of agent-written vs human-written tests</li><li>a replication of an AIDev-style acceptance analysis on public data</li></ul><p><strong>IRB caution.</strong> Studies must not intervene on maintainers or other students without IRB review. The 2021 UMN case shows the cost of getting this wrong.</p><p><strong>Inference:</strong> the presentation role structure (presenter, discussant, Perusall questions) lets undergraduates attend graduate presentations as a graded audience at low cost.</p><hr><h2 id="q4-semester-length-1416-week-ai-assisted-courses-for-students-with-one-programming-course-course-a" tabindex="-1">Q4. Semester-length (14–16 week) AI-assisted courses for students with one programming course (Course A) <a class="header-anchor" href="#q4-semester-length-1416-week-ai-assisted-courses-for-students-with-one-programming-course-course-a" aria-label="Permalink to &quot;Q4. Semester-length (14–16 week) AI-assisted courses for students with one programming course (Course A)&quot;">​</a></h2><h3 id="cmu-15-113-effective-coding-with-ai-spring-2026-the-full-semester-version" tabindex="-1">CMU 15-113 &quot;Effective Coding with AI&quot;, Spring 2026: the full-semester version <a class="header-anchor" href="#cmu-15-113-effective-coding-with-ai-spring-2026-the-full-semester-version" aria-label="Permalink to &quot;CMU 15-113 &quot;Effective Coding with AI&quot;, Spring 2026: the full-semester version&quot;">​</a></h3><p><strong>Logistics and grading</strong></p><ul><li>Prereq: 15-112. 6 hrs/week (3 in class plus 3 outside). Two 80-minute meetings a week. — <a href="https://www.cs.cmu.edu/~mdtaylor/113/S26/" target="_blank" rel="noreferrer">15-113 S26 archive</a></li><li>Grading: homework (about 10) 20%, &quot;based on evidence of effort&quot;; participation 20%; three big projects 40%; &quot;infrequent quizzes + 2 exams&quot; 20%, which &quot;will mostly ask you to reflect on tools and strategies&quot;. — <a href="https://www.cs.cmu.edu/~mdtaylor/113/S26/" target="_blank" rel="noreferrer">15-113 S26 archive</a></li></ul><p><strong>Three-phase, 14-week schedule</strong> — <a href="https://www.cs.cmu.edu/~mdtaylor/113/S26/" target="_blank" rel="noreferrer">15-113 S26 archive</a></p><ul><li><strong>Phase 1, Tools and Exploration (W1–4):</strong> first build and HTML crash course; Copilot; Project 1 portfolio due W2; &quot;Tetris 3 ways&quot; (naive prompting, Plan-Adjust-Execute, detailed prompts) and HW2 Crossy Road; APIs, &quot;Build a chatbot in Python&quot;, HW3 Explore an API.</li><li><strong>Phase 2, Strategic Mastery (W5–9):</strong> backend basics and HW4 Frontend + Backend; AI, labor, and learning with HW5 readings; Project 2 due W7; spring break; databases and SQLite (guest: &quot;Why AI+SQL is Hard&quot;), HW6; case studies, Project 2 showcase, HW7 Code Handoff.</li><li><strong>Phase 3, Capstones and Best Practices (W10–14):</strong> multi-agent workflows and HW8 &quot;The Agentic Build&quot;; phone apps with Expo (HW9); RAG; &quot;The Agentic Frontier&quot; and Project 3 checkpoint; &quot;How does GenAI work?&quot;, best practices, Project 3 due.</li></ul><p><strong>How the extra weeks are used</strong></p><ul><li><p>The Fall 2026 7-week mini (15-113) covers essentially Spring&#39;s weeks 1–7. The rest moved to the second mini, 15-114: databases, case studies, the cutting edge, phone apps, RAG, final topics, and Project 3. — <a href="https://www.cs.cmu.edu/~113/" target="_blank" rel="noreferrer">15-113 F26 site</a>; compare <a href="https://www.cs.cmu.edu/~mdtaylor/113/S26/" target="_blank" rel="noreferrer">S26 archive</a></p></li><li><p><strong>Inference:</strong> going from the 7-week to the full semester version adds four things:</p><ul><li>(a) a data/persistence unit</li><li>(b) a code-handoff exercise that tests documentation</li><li>(c) spec-driven agentic work from a hand-written SPEC.md</li><li>(d) a third, more ambitious capstone plus reflection weeks</li></ul><p>Agents arrive only in week 10.</p></li></ul><p><strong>Bridging Python to the web</strong></p><ul><li>Project 1 assumes &quot;Most students have never built a website before&quot;. It asks students to &quot;use AI as a learning tool to master new domains (HTML, CSS, JavaScript)&quot;, with a reflection written without AI. — <a href="https://www.cs.cmu.edu/~mdtaylor/113/S26/" target="_blank" rel="noreferrer">15-113 S26 archive</a></li><li>Python stays in use for the API chatbot, the SQLite CLI, and the Render backend. — <a href="https://www.cs.cmu.edu/~mdtaylor/113/S26/" target="_blank" rel="noreferrer">15-113 S26 archive</a></li><li>In Fall 2026, Crossy Road moved from a one-hour Python build to &quot;a playable JavaScript game&quot; published on the portfolio. — <a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">F26 report</a></li></ul><p><strong>Instructor&#39;s draft paper</strong> (marked &quot;in submission&quot;; linked from the course site; paraphrased here) — <a href="https://www.cs.cmu.edu/~113/SIGCSE_draft.pdf" target="_blank" rel="noreferrer">draft PDF</a></p><ul><li>Audience: designed for first-year students who have taken one rigorous programming course (AP CS A level or above). About 50 enrolled. 95% named Python as their most comfortable language.</li><li>HW4 (deployed secure backend) and HW9 (phone apps) were the two hardest. Unsuccessful students on HW4 most often got stuck &quot;in a prompting loop for hours&quot; and did not seek help.</li><li>After spec-driven development was introduced, students who had the AI write their SPEC.md found the agent&#39;s output constrained in ways they did not want. Peer experience changed behavior more than instructor warnings did.</li><li>In HW7 (code handoff), most students had documented with AI. Most found inherited code documented in enough detail.</li><li>Students struggled to top their Project 2 idea in Project 3. The instructor suggests saving the best idea for the end.</li></ul><h3 id="brown-university-agentic-studio-spring-2026-and-csci-0111e-fall-2026" tabindex="-1">Brown University: Agentic Studio (Spring 2026) and CSCI 0111E (Fall 2026) <a class="header-anchor" href="#brown-university-agentic-studio-spring-2026-and-csci-0111e-fall-2026" aria-label="Permalink to &quot;Brown University: Agentic Studio (Spring 2026) and CSCI 0111E (Fall 2026)&quot;">​</a></h3><p><strong>Agentic Studio (Spring 2026)</strong></p><ul><li>Taught by Kathi Fisler, Shriram Krishnamurthi, and Michael Littman. Required &quot;at least one prior computer science course&quot;. About 20 students were admitted from about 80 applicants. — <a href="https://www.brown.edu/news/2026-06-11/agentic-studio-ai-programming" target="_blank" rel="noreferrer">Brown news, 2026-06-11</a></li><li>Projects (teams, Claude Code, journals throughout): an upside-down Tetris, a graduation-requirements checker, and a Signal-like messaging app. — <a href="https://www.brown.edu/news/2026-06-11/agentic-studio-ai-programming" target="_blank" rel="noreferrer">Brown news, 2026-06-11</a></li><li><strong>Code reviews in which students explained and defended their decisions</strong> were central (paraphrase of the article). Agent code was often buggy, hallucinated details, and was poorly structured for later expansion; flipping Tetris exposed this. — <a href="https://www.brown.edu/news/2026-06-11/agentic-studio-ai-programming" target="_blank" rel="noreferrer">Brown news, 2026-06-11</a></li><li>Related SIGCSE 2027 paper: &quot;Accountability in an Era of Agentic GenAI Coding&quot; (Fisler, Krishnamurthi, Littman). — <a href="https://2027.sigcse-ts.acm.org/track/sigcse-ts-2027-Papers-1" target="_blank" rel="noreferrer">SIGCSE TS 2027 papers</a></li></ul><p><strong>CSCI 0111E (Fall 2026) design</strong></p><ul><li>Students write specifications for structure, behavior, and testing, then use LLMs or agents to create, validate, or audit from them (paraphrase). The work centers on tabular data.</li><li>&quot;The first two months of the course will use only LLMs; we&#39;ll switch to agents in the last month.&quot;</li><li>A reflection journal runs throughout.</li><li>— <a href="https://cs.brown.edu/courses/csci0111e/fall26/course-design.html" target="_blank" rel="noreferrer">CSCI 0111E course design</a></li></ul><h3 id="other-semester-length-models" tabindex="-1">Other semester-length models <a class="header-anchor" href="#other-semester-length-models" aria-label="Permalink to &quot;Other semester-length models&quot;">​</a></h3><p><strong>ANU COMP4020 (12 weeks)</strong> makes the bridge explicit: client-side static apps on GitHub Pages until week 7, then a server and database on Fly.io, with a weekly in-person crit on small, varied briefs (&quot;Forgotten web&quot;, &quot;An instrument&quot;, &quot;A game&quot;, &quot;The ANU system you wish existed&quot;). — <a href="https://comp.anu.edu.au/courses/comp4020-agentic-coding-studio/" target="_blank" rel="noreferrer">ANU course site</a>; <a href="https://comp.anu.edu.au/courses/comp4020-agentic-coding-studio/lectures/" target="_blank" rel="noreferrer">ANU lectures</a></p><p><strong>UMD CMSC 389A</strong> goes from Python FastAPI to MySQL to React/TypeScript in weeks 2–3, but its prereq is two sophomore courses. — <a href="https://www.cs.umd.edu/class/fall2026/cmsc389A/Schedule.html" target="_blank" rel="noreferrer">389A schedule</a></p><p><strong>&quot;Programming with GenAI&quot; (course 11102, Fall 2025)</strong> shows the opposite assessment design: &quot;80% of the course grade comes from GenAI-free proctored assessments&quot;. — <a href="https://ialbluwi.github.io/11102-f25/genai" target="_blank" rel="noreferrer">11102 GenAI page</a></p><h3 id="takeaway-for-course-a" tabindex="-1">Takeaway for Course A <a class="header-anchor" href="#takeaway-for-course-a" aria-label="Permalink to &quot;Takeaway for Course A&quot;">​</a></h3><p><strong>How to use the extra weeks</strong> (inference from CMU&#39;s 7- vs 14-week versions, Brown, and ANU):</p><ul><li><strong>Keep the 8-week course&#39;s first half nearly intact, and spread it out.</strong> That means portfolio, timed game sprint, API, and frontend plus backend, with more reflection and debrief time.</li><li><strong>Spend the added weeks on the topics that were thin or failed in short versions:</strong><ul><li>a persistence/database unit, where CMU&#39;s understanding scores peaked</li><li>a code-handoff week as the first &quot;existing code&quot; experience</li><li>spec-driven agent work only after week 9–10, with a hand-written spec</li><li>a security/deploy week for secrets and row-level security</li><li>a third project that is the real capstone</li></ul></li><li><strong>Introduce agents late.</strong> CMU did so at week 10 of 14 and Brown in the last month. Pair the agent weeks with code review and defense of decisions, which Brown found essential.</li><li><strong>Bridge from Python to JavaScript the way CMU and ANU do:</strong><ul><li>First project: an AI-built static HTML/CSS/JS site on GitHub Pages.</li><li>Small Python scripts (API calls, SQLite) stay in parallel.</li><li>Then a Python backend (FastAPI/Flask) behind a JavaScript frontend.</li><li>Avoid mobile apps. CMU found them the hardest and the least understood.</li></ul></li></ul><hr><h2 id="q5-labs-that-worked-or-failed" tabindex="-1">Q5. Labs that worked or failed <a class="header-anchor" href="#q5-labs-that-worked-or-failed" aria-label="Permalink to &quot;Q5. Labs that worked or failed&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lab type</th><th>Where</th><th>What happened / evidence</th></tr></thead><tbody><tr><td><strong>Build-your-own agent</strong></td><td>Stanford CS146S F26 W1 lecture &quot;build Claude Code in 200 lines&quot; plus a graded trace dissection (baseline); Michigan&#39;s planned &quot;Build the agent&quot; lab</td><td>Michigan <strong>replaced</strong> its own-agent lab and dropped its eval suite and teardown after student feedback. Students now extend Aider. — <a href="https://github.com/eecs498-aase/materials/blob/HEAD/labs/Lab03/slides.md" target="_blank" rel="noreferrer">Lab03</a>; <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">syllabus</a>. UT Austin teaches the loop through decks (&quot;Claude Code Unpacked… mapped from source&quot;) rather than a build. — <a href="https://www.cs.utexas.edu/~witchel/378AC/schedule.html" target="_blank" rel="noreferrer">schedule</a>. Reference implementations: mini-swe-agent, about &quot;100 lines of python&quot;, bash only, &quot;&gt;74% on the SWE-bench verified&quot; — <a href="https://github.com/SWE-agent/mini-swe-agent" target="_blank" rel="noreferrer">repo</a>; Thorsten Ball&#39;s Go agent, &quot;less than 400 lines&quot;, three tools — <a href="https://ampcode.com/how-to-build-an-agent" target="_blank" rel="noreferrer">Amp</a></td></tr><tr><td><strong>Mutation testing of AI tests</strong></td><td>No course experience report found</td><td>Michigan&#39;s rubric: &quot;Tests earn credit for detecting plausible defects&quot; — <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">syllabus</a>. UMD 389A lists &quot;evaluate AI-generated test suites&quot; — <a href="https://www.cs.umd.edu/class/fall2026/cmsc389A/Syllabus.html" target="_blank" rel="noreferrer">syllabus</a>. Research motivation: suites with 100% coverage can have only 4% mutation score — <a href="https://arxiv.org/html/2506.02954v5" target="_blank" rel="noreferrer">MutGen arXiv 2506.02954</a>. An ICSE CSEE&amp;T 2025 tool for intro assignments raised mutation scores 2.1× and found new bugs in 13% of 1,296 submissions (search summary) — <a href="https://conf.researchr.org/details/icse-2025/cseet-2025-papers/17/Automatic-Unit-Test-Generation-for-Programming-Assignments-Using-Large-Language-Model" target="_blank" rel="noreferrer">CSEE&amp;T 2025</a></td></tr><tr><td><strong>AI vs human PR review</strong></td><td>CS146S F25 W7 (baseline); a master&#39;s SE capstone (Oliveira et al.)</td><td>Oliveira et al. (ICSE-SEET 2026), more than 100 students: PRs rose from 581 to 1,176; failed AI reviews fell from 227 to 0 after &quot;tool and instructional refinements&quot;; adoption was 93% then 50% of teams; 32–33% of AI-reviewed PRs got follow-up commits — <a href="https://arxiv.org/abs/2604.23251" target="_blank" rel="noreferrer">arXiv 2604.23251</a>. UT Austin&#39;s peer PR round runs on a fixed clock with explicit consequences for no-shows — <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">home</a></td></tr><tr><td><strong>Prompt injection / sandboxing</strong></td><td>UT Austin W3 (&quot;Prompt injection and the lethal trifecta&quot;, &quot;Permissions and sandboxing&quot;), W9 (&quot;Using secrets safely with agents&quot;); UVA W13 &quot;Red teaming&quot;; Cornell &quot;Security of Agents&quot; papers</td><td>Schedules only; no outcome data published — <a href="https://www.cs.utexas.edu/~witchel/378AC/schedule.html" target="_blank" rel="noreferrer">UT schedule</a>; <a href="https://www.cs.virginia.edu/~se4ja/files/seLLMs2026.html" target="_blank" rel="noreferrer">UVA</a>; <a href="https://www.cs.cornell.edu/courses/cs6158/2026fa/schedule.html" target="_blank" rel="noreferrer">Cornell</a>. Michigan&#39;s planned &quot;repo that tries to prompt-inject your agent&quot; (baseline) is not in the post-pivot plan — <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">syllabus</a></td></tr><tr><td><strong>Eval harness</strong></td><td>Michigan (dropped); CS146S W5 readiness comparison; UT W13 &quot;Rewards and benchmarks&quot;</td><td>The surviving form is comparative and small-sample, with explicit claim scoping: &quot;Three repos is a small sample&quot; — <a href="https://github.com/mihail911/modern-software-dev-assignments/blob/df18839a81/week5/assignment.md" target="_blank" rel="noreferrer">W5 spec</a></td></tr><tr><td><strong>Legacy / brownfield code</strong></td><td>CMU 17-316 Hextris activity; CMU 17-313 opencode + Qlty; Michigan Aider; CS146S W4 AGENTS.md</td><td>17-316: use Cursor to understand Hextris, generate docs, explain them to a neighbor (&quot;Is it good? Correct?&quot;), add a color block, then vote on features — <a href="https://ai-developer-tools.github.io/assets/pdfs/02-brownfield-vibe-coding-activity.pdf" target="_blank" rel="noreferrer">slides</a>. 17-313 starts with a measurable refactor (remove a Qlty smell) — <a href="https://cmu-313.github.io/assignments/P1/2_refactoring/" target="_blank" rel="noreferrer">P1B</a>. Brown: extending agent-built Tetris exposed poor structure — <a href="https://www.brown.edu/news/2026-06-11/agentic-studio-ai-programming" target="_blank" rel="noreferrer">Brown news</a></td></tr><tr><td><strong>Parallel agents</strong></td><td>UT W4 &quot;Parallelize a task once you can name its merge point&quot;; UMD 389A worktrees; CS146S F25 W5 Warp; CMU 15-113 S26 W13 &quot;True Multi-Agent Teams&quot;</td><td>Topics and demos only. CMU&#39;s agent-teams demo was labeled &quot;in progress&quot; — <a href="https://www.cs.cmu.edu/~mdtaylor/113/S26/" target="_blank" rel="noreferrer">S26 archive</a>; <a href="https://www.cs.utexas.edu/~witchel/378AC/schedule.html" target="_blank" rel="noreferrer">UT schedule</a></td></tr><tr><td><strong>Spec changes mid-assignment</strong></td><td>UT Austin &quot;beats&quot;</td><td>Built into every homework — <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">home</a></td></tr></tbody></table><h3 id="takeaway-for-course-a-1" tabindex="-1">Takeaway for Course A <a class="header-anchor" href="#takeaway-for-course-a-1" aria-label="Permalink to &quot;Takeaway for Course A&quot;">​</a></h3><p><strong>What evidence supports</strong></p><ul><li>Labs on existing code work when they start with comprehension. In the 17-316 Hextris activity, students explain AI-generated docs to a neighbor before changing anything.</li><li>CMU&#39;s code-handoff week is a cheap, proven option.</li><li>Avoid mobile apps and multi-agent teams, which were the hardest and least understood.</li></ul><p><strong>Where security fits</strong></p><ul><li>Security is better taught through the student&#39;s own deployed app (secrets, keys) than through an abstract injection lab.</li><li><strong>Inference:</strong> a short &quot;your agent read a malicious README&quot; demo in the agent weeks is enough at this level.</li></ul><h3 id="takeaway-for-course-b-3" tabindex="-1">Takeaway for Course B <a class="header-anchor" href="#takeaway-for-course-b-3" aria-label="Permalink to &quot;Takeaway for Course B&quot;">​</a></h3><p><strong>Sequencing the labs</strong></p><ul><li>Keep the 200-line agent as a <strong>one-week</strong> lab, with a mini-swe-agent-style bash-only design and a trace dissection.</li><li>Then move straight into extending a real harness or codebase. This is how both Michigan and CMU 17-313 converged on &quot;large existing codebase&quot; learning.</li><li>Teach prompt injection with UT Austin&#39;s framing (lethal trifecta, then permissions and sandboxing, then secrets for agents) in weeks 3–4, before students give agents broad access in the team project.</li></ul><p><strong>Mutation testing and AI review</strong></p><ul><li>Mutation testing of AI-written tests is an <strong>open niche</strong>: no course has published results. It suits a graduate empirical study and a Course B lab graded on mutation score rather than coverage.</li><li>For AI vs human review, the Oliveira et al. capstone data say tooling reliability and instructions matter more than the model. Pilot the review bot before students depend on it.</li></ul><hr><h2 id="gaps" tabindex="-1">Gaps <a class="header-anchor" href="#gaps" aria-label="Permalink to &quot;Gaps&quot;">​</a></h2><ul><li><strong>Unpublished:</strong> CS146S&#39;s open-source rubric and outcomes; UT Austin&#39;s in-class &quot;Lessons from…&quot; sessions; Michigan&#39;s Create phase and weeks 11–15; Brown&#39;s Agentic Studio syllabus and weights.</li><li><strong>Not read:</strong> NC State GAI4SE&#39;s syllabus (Google Doc), UNC Charlotte ITCS 6010/8010&#39;s syllabus PDF, ANU COMP4020&#39;s prerequisites and AI policy.</li><li><strong>No outcome data</strong> were found for mutation-testing, prompt-injection, or parallel-agent labs, or on 2026 merge rates for student PRs since maintainer AI policies tightened.</li><li><strong>Secondary only:</strong> GitHub&#39;s June 2026 PR-cap details and the AIDev acceptance percentages come from search summaries; the CMU draft paper is unpublished and marked do-not-distribute.</li></ul>',141)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
